import {esc,icon,badge,avatar,progress,empty,fmt,money} from './ui.js';
import {initStudio,createProcess,editDraft,undoDraft,redoDraft,discardDraft,publishDraft,validateDraft,patchStep,addStep,duplicateStep,removeStep,patchStage,addStage,removeStage,setEdges,updateSetup,startRun,resolveApproval,reassignApproval,getFitCandidates,naturalChange,applyImprovement,studioProcess,diffDraft,listTemplates,cancelRun,advanceRun} from './workflow-store.js';

const view={processId:null,tab:'design',lens:'design',runFilter:'all',runId:null,zoom:0.8,showChanges:false};
const tabs=[['design','Conception'],['runs','Exécutions'],['overview','Vue d’ensemble'],['setup','Configuration']];
const runLabels={running:'En cours',waiting:'Décision requise',completed:'Terminé',failed:'Arrêté'};
const kindLabels={agent:'Agent',human:'Humain',tool:'Outil / contrôle'};
const autonomyLabels={supervised:'Sous mandat avec escalade',approval:'Validation de chaque résultat',observe:'Observation et test'};
const clone=v=>JSON.parse(JSON.stringify(v));
const button=(action,label,{id='',value='',className='',iconName='',attrs=''}={})=>`<button type="button" class="btn ${className}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''} ${value?`data-value="${esc(value)}"`:''} ${attrs}>${iconName?icon(iconName,15):''}${label}</button>`;
const options=(items,value)=>items.map(i=>`<option value="${esc(typeof i==='string'?i:i.id)}" ${(typeof i==='string'?i:i.id)===value?'selected':''}>${esc(typeof i==='string'?i:i.name)}</option>`).join('');
const humanOptions=(s,value)=>options(s.agents.filter(a=>a.type==='human').map(a=>a.name),value);
const actor=(s,id)=>s.agents.find(a=>a.id===id);
const nodeName=(snapshot,id)=>snapshot.nodes.find(n=>n.id===id)?.name||id;
const dirty=p=>JSON.stringify(p.draft)!==JSON.stringify(p.published);
const statusBadge=status=>badge(runLabels[status]||status,status==='completed'?'green':status==='waiting'?'amber':status==='failed'?'red':'purple');
const time=v=>v?new Date(v).toLocaleString('fr-FR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'—';
const processRuns=(s,id)=>s.studio.runs.filter(r=>r.processId===id);
const isAlwaysEligible=(run)=>run.snapshot.nodes.find(n=>n.id===run.request?.nodeId)?.kind!=='human' && run.request?.eligibleForAlways!==false;
const finish=(result,ctx,message)=>{if(result?.ok===false){ctx.toast(result.error||(result.errors||[]).join(' · ')||'Cette action est impossible.');return false;}ctx.toast(message||result?.explanation||'Modification enregistrée.');return true;};

export function initWorkflows(){return initStudio();}
export function getWorkflowSidebar(s){return (s.studio?.processes||[]).map(p=>({id:p.id,name:p.name,detail:p.status==='draft'?'Brouillon':p.status==='paused'?'Suspendu':`${(s.studio.runs||[]).filter(r=>r.processId===p.id&&!['completed','failed'].includes(r.status)).length} dossier(s) ouvert(s)`,pending:(s.studio.runs||[]).filter(r=>r.processId===p.id&&r.status==='waiting').length}));}
export function getWorkflowInterventions(s){return (s.studio?.runs||[]).filter(r=>r.status==='waiting'&&r.request).map(r=>({id:r.id,processId:r.processId,title:r.request.title,detail:r.title,owner:r.request.owner,agentId:r.request.agentId}));}
export function openWorkflow(id,ctx){view.processId=id;view.tab='design';view.runId=null;view.showChanges=false;ctx.closeDrawer?.();ctx.navigate('processes');ctx.render();}
export function openWorkflowRun(id,ctx){const r=ctx.getState().studio?.runs.find(r=>r.id===id);if(!r){ctx.toast('Exécution introuvable.');return;}view.processId=r.processId;view.runId=r.id;view.tab='runs';view.runFilter='all';ctx.closeDrawer?.();ctx.navigate('processes');ctx.render();}

function renderIndex(s){
 const list=s.studio.processes;
 const waiting=s.studio.runs.filter(r=>r.status==='waiting').length;
 return `<header class="page-head"><div><div class="eyebrow">LE TRAVAIL, DE BOUT EN BOUT</div><h1 class="page-title">Quel résultat voulez-vous obtenir ?</h1><p class="page-description">Définissez le résultat. Composez les étapes, les agents et les décisions qui restent humaines.</p></div>${button('wf-open','Explorer un processus',{id:'p-rfp',iconName:'workflow'})}</header>
 <section class="wf-outcome-card"><div class="wf-outcome-icon">${icon('workflow',25)}</div><div class="wf-outcome-body"><label for="wf-outcome"><strong>Commencer par l’objectif</strong></label><textarea id="wf-outcome" placeholder="Ex. Répondre à chaque appel d’offres en trois jours, avec un dossier sourcé et validé." rows="3"></textarea><div class="row between"><span class="small muted">Construction locale à partir de modèles · aucune génération IA distante</span>${button('wf-create','Préparer le processus',{className:'btn-primary',iconName:'arrow'})}</div></div></section>
 <div class="wf-template-list">${listTemplates().map(t=>button('wf-template',esc(t.title||t.name),{id:t.id,className:'btn-sm'})).join('')}</div>
 <div class="wf-summary-line"><strong>${list.filter(p=>p.status==='live').length}</strong> processus en service <span>·</span><strong>${waiting}</strong> décisions humaines en attente <span>·</span><strong>${s.studio.runs.length}</strong> dossiers de démonstration</div>
 <div class="wf-process-grid">${list.map(p=>{const runs=processRuns(s,p.id);const pending=runs.filter(r=>r.status==='waiting').length;const d=p.published||p.draft;return `<button class="card wf-process-tile" data-action="wf-open" data-id="${esc(p.id)}"><div class="row between"><span class="wf-process-icon">${icon('workflow',21)}</span>${pending?badge(`${pending} décision${pending>1?'s':''}`,'amber'):badge(p.status==='paused'?'Suspendu':p.status==='draft'?'Brouillon':'En service',p.status==='live'?'green':'neutral')}</div><h2>${esc(p.name)}</h2><p>${esc(d.outcome)}</p><div class="wf-tile-owner">${avatar(actor(s,p.leadAgentId)||{type:'agent'})}<span>Coordonné par <strong>${esc(actor(s,p.leadAgentId)?.name||'Agent à affecter')}</strong><br><small>Sous la responsabilité de ${esc(p.owner)}</small></span></div><div class="wf-tile-foot"><span><strong>${d.nodes.length}</strong> étapes</span><span><strong>${d.stages.length}</strong> phases</span><span>Version <strong>${p.version||0}</strong></span>${icon('arrow',16)}</div></button>`;}).join('')}</div>
 <div class="notice"><div><strong>Des responsabilités explicites, à chaque étape.</strong><p>Chaque dossier conserve la version utilisée au démarrage. Les modifications sont préparées dans un brouillon avant publication.</p></div></div>`;
}

export function renderWorkflows(s){
 if(!s.studio)return `<div class="empty"><h3>Initialisation du studio…</h3></div>`;
 const p=studioProcess(s,view.processId);
 if(!p)return renderIndex(s);
 const hasChanges=dirty(p);const pending=processRuns(s,p.id).filter(r=>r.status==='waiting').length;
 return `<div class="wf-workspace"><div class="wf-workspace-head"><div class="wf-heading"><button class="icon-button" data-action="wf-back" aria-label="Tous les processus">${icon('arrow',17)}</button><span class="wf-process-icon">${icon('workflow',20)}</span><div><h1>${esc(p.name)}</h1><p><span class="status-dot ${p.status==='live'?'positive':''}"></span> ${p.status==='live'?'En service':p.status==='paused'?'Suspendu':'Brouillon'} · version ${p.version||0}${hasChanges?' · modifications non publiées':''} · ${esc(actor(s,p.leadAgentId)?.name||'À affecter')}</p></div></div><div class="wf-workspace-actions">${button('wf-test','Tester',{iconName:'play',className:'btn-sm'})}${button('wf-improvements',`Améliorer ${badge((p.improvements||[]).filter(x=>!x.applied).length,'amber')}`,{className:'btn-sm'})}${button('wf-publish',hasChanges?`Publier la version ${(p.version||0)+1}`:'Version publiée',{className:hasChanges?'btn-primary btn-sm':'btn-sm',iconName:hasChanges?'arrowUp':'check'})}</div></div>
 <div class="wf-tabbar"><div class="wf-tabs">${tabs.map(([key,label])=>`<button class="${view.tab===key?'active':''}" data-action="wf-tab" data-value="${key}">${label}${key==='runs'&&pending?`<span>${pending}</span>`:''}</button>`).join('')}</div><span class="wf-demo-indicator">Données et exécutions simulées</span></div>
 ${hasChanges?`<div class="wf-draft-strip"><div class="row">${badge(`Brouillon ${(p.version||0)+1}`,'purple')}<span>Modifications isolées de la version en service</span></div><div class="row">${button('wf-diff',view.showChanges?'Masquer les changements':'Voir les changements',{className:'btn-ghost btn-sm',iconName:'edit'})}${button('wf-discard','Abandonner le brouillon',{className:'btn-ghost btn-sm'})}</div></div>`:''}
 ${view.showChanges?renderDiff(p):''}
 ${view.tab==='design'?renderDesign(p,s):view.tab==='runs'?renderRuns(p,s):view.tab==='overview'?renderOverview(p,s):renderSetup(p,s)}
 </div>`;
}

function renderDiff(p){
 const result=diffDraft(p.id);const changes=Array.isArray(result)?result:result.changes||[];
 return `<section class="wf-diff"><strong>Différences avec la version ${p.version||0}</strong>${changes.length?changes.map(c=>`<div><span>${esc(c.label||c.path||c.type||'Modification')}</span><del>${esc(typeof c.before==='object'?JSON.stringify(c.before):c.before??'—')}</del><span>${icon('arrow',12)}</span><ins>${esc(typeof c.after==='object'?JSON.stringify(c.after):c.after??'—')}</ins></div>`).join(''):'<p class="small muted">Les versions sont identiques.</p>'}</section>`;
}

function designLayout(d){
 const stageWidth=252;const nodeWidth=216;const rowHeight=158;const stageNodes=d.stages.map(stage=>d.nodes.filter(n=>n.stageId===stage.id));
 const positions={};stageNodes.forEach((nodes,col)=>nodes.forEach((n,row)=>positions[n.id]={x:col*stageWidth+18,y:102+row*rowHeight,w:nodeWidth,h:130}));
 return {positions,rowHeight,width:d.stages.length*stageWidth,height:Math.max(530,Math.max(...stageNodes.map(n=>n.length),1)*rowHeight+188),stageWidth,stageNodes};
}

function renderDesign(p,s){
 const selectedRun=processRuns(s,p.id).find(r=>r.id===view.runId)||processRuns(s,p.id).find(r=>r.status==='waiting')||processRuns(s,p.id)[0];
 const d=view.lens==='live'?(selectedRun?.snapshot||p.published||p.draft):p.draft;const l=designLayout(d);const validation=validateDraft(d);
 const completedSteps=selectedRun?.steps||[];
 return `<div class="wf-designer"><div class="wf-canvas-toolbar"><div class="row"><div class="wf-history-buttons"><button class="icon-button" data-action="wf-undo" aria-label="Annuler la dernière modification" ${(p.undo||[]).length?'':'disabled'}>${icon('refresh',15)}</button><button class="icon-button wf-redo" data-action="wf-redo" aria-label="Rétablir la modification" ${(p.redo||[]).length?'':'disabled'}>${icon('refresh',15)}</button></div>${validation.ok?badge('Structure valide','green'):button('wf-validation',`${validation.errors.length} point(s) à corriger`,{className:'wf-validate-warning btn-sm',iconName:'alert'})}${button('wf-connections','Dépendances',{className:'btn-sm',iconName:'workflow'})}${button('wf-add-stage','Ajouter une phase',{className:'btn-ghost btn-sm',iconName:'plus'})}</div><div class="wf-lenses">${[['design','Conception'],['live',`En service${selectedRun?' · '+(selectedRun.status==='waiting'?'attente':'simulation'):''}`],['performance','Performance']].map(([key,label])=>`<button class="${view.lens===key?'active':''}" data-action="wf-lens" data-value="${key}">${label}</button>`).join('')}</div></div>
 ${view.lens==='live'?`<div class="wf-lens-note">Version ${selectedRun?.version||p.version}. ${selectedRun?`Le dossier « ${esc(selectedRun.title)} » est affiché sur son instantané conservé.`:'Aucune exécution.'} Les modifications s’effectuent dans la vue Conception.</div>`:''}
 ${view.lens==='performance'?'<div class="wf-lens-note">Durées de référence du scénario et exécutions locales. Les écarts signalent des pistes à examiner, sans prédiction de gain réel.</div>':''}
 <div class="wf-trigger-row"><button data-action="wf-edit-setup" class="wf-trigger">${icon('clock',15)}<span><small>DÉCLENCHEMENT</small><strong>${esc(typeof d.trigger==='object'?d.trigger.label||'Événement métier':d.trigger||'À la demande')}</strong></span>${icon('edit',12)}</button><span class="wf-trigger-arrow">${icon('arrow',16)}</span><div><strong>${esc(d.stages[0]?.name||'Première phase')}</strong><small>Objectif de remise · ${fmt(d.deadlineHours||72)} h</small></div></div>
 <div class="wf-canvas-scroll" id="wf-canvas-scroll"><div class="wf-canvas-sizer" style="width:${l.width*view.zoom}px;height:${l.height*view.zoom}px"><div class="wf-canvas" style="width:${l.width}px;height:${l.height}px;transform:scale(${view.zoom})">
 ${d.stages.map((st,i)=>`<section class="wf-stage" style="left:${i*l.stageWidth}px;width:${l.stageWidth}px;height:${l.height}px"><button class="wf-stage-head" data-action="wf-stage" data-id="${esc(st.id)}"><span class="wf-stage-index">${i+1}</span><span><strong>${esc(st.name)}</strong><small>Sous ${fmt(st.deadlineHours)} h · ${l.stageNodes[i].length} étapes</small><small>${fmt(l.stageNodes[i].filter(n=>n.kind==='human').reduce((v,n)=>v+(Number(n.estimatedMinutes)||0),0))} min humaines · ${fmt(l.stageNodes[i].filter(n=>n.kind!=='human').reduce((v,n)=>v+(Number(n.estimatedMinutes)||0),0))} min agents</small></span>${icon('more',15)}</button>${view.lens!=='live'?`<button class="wf-add-node" data-action="wf-add-step" data-id="${esc(st.id)}" style="top:${116+l.stageNodes[i].length*l.rowHeight}px">${icon('plus',15)} Ajouter une étape</button>`:''}</section>`).join('')}
 <svg class="wf-edges" width="${l.width}" height="${l.height}" aria-label="Liens et dépendances entre les étapes"><defs><marker id="wf-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10 Z" fill="#bdc3ce"/></marker></defs>${(d.edges||[]).map(edge=>{const a=l.positions[edge.from],b=l.positions[edge.to];if(!a||!b)return'';let path='',tx=0,ty=0;if(a.x===b.x){const sx=a.x+a.w/2,sy=a.y+a.h,ex=b.x+b.w/2,ey=b.y;path=`M${sx},${sy} L${sx},${sy+15} L${ex},${sy+15} L${ex},${ey-4}`;tx=sx+7;ty=(sy+ey)/2;}else{const sx=a.x+a.w,sy=a.y+a.h/2,ex=b.x,ey=b.y+b.h/2,mx=(sx+ex)/2;path=`M${sx},${sy} L${mx},${sy} L${mx},${ey} L${ex-4},${ey}`;tx=mx+5;ty=Math.min(sy,ey)-7;}return `<path d="${path}" fill="none" stroke="#c3c7cf" stroke-width="1.4" marker-end="url(#wf-arrow)"/>${edge.label?`<text x="${tx}" y="${ty}" fill="#9297a3" font-size="9">${esc(edge.label)}</text>`:''}`;}).join('')}</svg>
 ${d.nodes.map(n=>{const pos=l.positions[n.id];if(!pos)return'';const staff=actor(s,n.agentId);const runStep=completedSteps.find(st=>st.nodeId===n.id);const waiting=selectedRun?.request?.nodeId===n.id;const fit=getFitCandidates(s,n).find(c=>c.id===n.agentId)||getFitCandidates(s,n)[0];return `<button class="wf-node ${n.kind==='human'?'wf-human-node':''} ${waiting&&view.lens==='live'?'wf-node-waiting':''}" style="left:${pos.x}px;top:${pos.y}px;width:${pos.w}px;height:${pos.h}px" data-action="wf-node" data-id="${esc(n.id)}"><div class="wf-node-main"><span class="wf-node-symbol">${icon(n.kind==='human'?'user':n.kind==='tool'?'shield':'bot',18)}</span><span><strong>${esc(n.name)}</strong><small>${esc(n.kind==='human'?n.owner:staff?.name||fit?.name||'À affecter')} · ${kindLabels[n.kind]||'Agent'}</small></span></div><div class="wf-node-tags">${view.lens==='performance'?`<span class="wf-duration ${Number(n.estimatedMinutes)>90?'slow':''}">${icon('clock',11)} ${fmt(n.estimatedMinutes||12)} min de référence</span>`:view.lens==='live'&&runStep?badge(waiting?'À vous de décider':runStep.status==='completed'?'Terminé':runStep.status==='waiting'?'En attente':'À venir',waiting?'amber':runStep.status==='completed'?'green':'neutral'):n.kind==='human'?badge('Décision humaine','amber'):badge(n.staffing==='shadow'?'Challenger en observation':n.staffing==='best'?'Meilleur profil disponible':'Affectation fixe','purple')}</div>${view.lens==='design'&&n.kind==='agent'&&fit?`<span class="wf-fit">${Math.round(fit.fit>1?fit.fit:fit.fit*100)}% d’adéquation simulée</span>`:''}</button>`;}).join('')}
 </div></div></div>
 <div class="wf-canvas-bottom"><div class="wf-zoom">${button('wf-zoom-out','−',{className:'btn-ghost btn-sm',attrs:'aria-label="Réduire"'})}<span>${Math.round(view.zoom*100)}%</span>${button('wf-zoom-in','+',{className:'btn-ghost btn-sm',attrs:'aria-label="Agrandir"'})}${button('wf-fit','Ajuster',{className:'btn-ghost btn-sm'})}</div><div class="wf-natural"><span class="avatar avatar-agent">${icon('bot',16)}</span><input id="wf-natural-request" aria-label="Demander une modification du processus" placeholder="Ex. Ajouter une validation humaine avant la remise…">${button('wf-natural','',{iconName:'arrow',className:'btn-primary btn-sm',attrs:'aria-label="Appliquer une demande de modification"'})}</div></div>
 <div class="wf-canvas-hint">Les demandes sont interprétées localement par des règles explicites. Essayez « validation humaine », « réduire le délai » ou « contrôle des sources ».</div></div>`;
}

function renderRuns(p,s){
 const all=processRuns(s,p.id);const filtered=all.filter(r=>view.runFilter==='all'||r.status===view.runFilter);const chosen=filtered.find(r=>r.id===view.runId)||filtered[0];
 if(chosen)view.runId=chosen.id;
 return `<div class="wf-runs"><aside class="wf-run-list"><div class="wf-run-filter">${[['all','Tous'],['running','En cours'],['waiting','En attente'],['completed','Terminés'],['failed','Arrêtés']].map(([key,label])=>`<button class="${view.runFilter===key?'active':''}" data-action="wf-run-filter" data-value="${key}">${label}<span>${key==='all'?all.length:all.filter(r=>r.status===key).length}</span></button>`).join('')}</div><div class="wf-run-list-actions">${button('wf-start','Nouveau dossier',{className:'btn-primary btn-sm',iconName:'plus'})}</div>${filtered.map(r=>`<button class="wf-run-row ${chosen?.id===r.id?'active':''}" data-action="wf-run-select" data-id="${esc(r.id)}"><span class="wf-run-dot ${r.status}"></span><span><strong>${esc(r.title)}</strong><small>${r.status==='waiting'?`${esc(r.request?.owner||p.owner)} · ${esc(r.request?.title||'Arbitrage')}`:runLabels[r.status]}</small><span>${r.isTest?'Test du brouillon':`Version ${r.version}`} · ${time(r.startedAt)}</span></span></button>`).join('')||empty('Aucun dossier','Lancez un dossier ou changez le filtre.')}</aside><section class="wf-run-detail">${chosen?renderRunDetail(chosen,p,s):`<div class="empty"><h3>Suivre un premier dossier</h3><p>Le parcours s’arrête à chaque décision humaine. Aucune action externe ne sera exécutée.</p>${button('wf-start','Lancer une simulation',{className:'btn-primary',iconName:'play'})}</div>`}</section></div>`;
}

function renderRunDetail(r,p,s){
 const request=r.request;const done=r.steps.filter(st=>st.status==='completed').length;const duration=r.metrics||{};
 return `<div class="wf-run-title"><div><div class="eyebrow">${r.isTest?'TEST LOCAL DU BROUILLON':'DOSSIER DE DÉMONSTRATION'}</div><h2>${esc(r.title)}</h2></div>${button('wf-follow','Voir sur le canevas',{id:r.id,className:'btn-sm',iconName:'workflow'})}</div><div class="wf-run-sub">${statusBadge(r.status)}<span>Démarré ${time(r.startedAt)}</span><span>Version ${r.version}${r.isTest?' · instantané du brouillon':''}</span></div>
 <div class="wf-run-metrics"><div><strong>${fmt(duration.agentMinutes||0)} min</strong><span>travail des agents</span></div><div><strong>${fmt(duration.humanMinutes||0)} min</strong><span>revue humaine</span></div><div><strong>${done} / ${r.snapshot.nodes.length}</strong><span>étapes terminées</span></div><div><strong>${money(duration.cost||0)}</strong><span>coût simulé</span></div></div>
 ${request&&r.status==='waiting'?`<div class="wf-waiting-banner"><span class="wf-run-dot waiting"></span><strong>${esc(request.owner)}, une décision vous revient</strong>${button('wf-reassign','Réaffecter',{id:r.id,className:'btn-ghost btn-sm',iconName:'users'})}</div><article class="wf-approval-card"><div class="row small muted">${icon('shield',16)} ${esc(actor(s,request.agentId)?.name||'Le processus')} propose cette action</div><h3>${esc(request.title)}</h3><p>${esc(request.reason||'Cette action dépasse la délégation ou requiert une revue explicite.')}</p><dl class="wf-request-grid"><dt>Processus</dt><dd>${esc(p.name)} · version ${r.version}</dd><dt>Étape</dt><dd>${esc(nodeName(r.snapshot,request.nodeId))}</dd><dt>Responsable</dt><dd>${esc(request.owner)}</dd><dt>Action</dt><dd><code>${esc(request.action||'review-result')}</code></dd><dt>Périmètre</dt><dd>Ce dossier et les arguments affichés</dd></dl><details class="wf-request-evidence"><summary>Examiner la demande complète et les preuves</summary><pre>${esc(JSON.stringify({action:request.action,processId:r.processId,nodeId:request.nodeId,agentId:request.agentId,version:r.version,arguments:request.arguments||request.payload||{},evidence:r.steps.find(st=>st.nodeId===request.nodeId)?.evidence||['Résultat simulé à examiner','Aucun effet externe']},null,2))}</pre></details><div class="row wf-approval-actions">${button('wf-approve','Autoriser une fois',{id:r.id,value:'once',className:'btn-primary',attrs:`data-request="${esc(request.id)}" data-token="${esc(request.token)}"`})}${isAlwaysEligible(r)?button('wf-approve','Toujours pour cette action',{id:r.id,value:'always',attrs:`data-request="${esc(request.id)}" data-token="${esc(request.token)}"`}):''}${button('wf-approve','Refuser',{id:r.id,value:'deny',className:'btn-danger',attrs:`data-request="${esc(request.id)}" data-token="${esc(request.token)}"`})}</div><p class="wf-approval-note">${isAlwaysEligible(r)?'Une autorisation récurrente ne vaut que pour cet agent, cette action et ce processus, à mandat inchangé.':'Cette étape humaine conserve une validation explicite à chaque dossier.'}</p></article>`:''}
 ${r.status==='failed'?`<div class="notice"><div><strong>Ce dossier est arrêté.</strong><p>${esc(r.error||r.events?.at(-1)?.detail||'Une décision de refus a interrompu le parcours. Aucun effet externe.')}</p></div></div>`:''}
 <h3 class="section-title">Parcours du dossier</h3><div class="wf-step-run-list">${r.snapshot.nodes.map(n=>{const step=r.steps.find(st=>st.nodeId===n.id);const state=step?.status||'pending';return `<details class="wf-step-run ${state}" ${request?.nodeId===n.id?'open':''}><summary><span class="wf-step-status">${icon(state==='completed'?'check':state==='waiting'?'clock':n.kind==='human'?'user':'bot',16)}</span><span><strong>${esc(n.name)}</strong><small>${esc(step?.actor||actor(s,n.agentId)?.name||n.owner||'À affecter')} · ${state==='completed'?`${fmt(step?.minutes||0)} min · ${money(step?.cost||0)}`:state==='waiting'?'En attente de décision':state==='failed'?'Arrêté':state==='skipped'?'Branche non retenue':'À venir'}</small></span>${badge(state==='completed'?'Terminé':state==='waiting'?'En attente':state==='failed'?'Arrêté':state==='skipped'?'Branche non retenue':'À venir',state==='completed'?'green':state==='waiting'?'amber':'neutral')}${icon('chevron',14)}</summary><div class="wf-step-run-body"><p>${esc(n.outcome)}</p>${step?.output?`<div class="wf-artifact"><strong>Résultat simulé</strong><p>${esc(typeof step.output==='object'?JSON.stringify(step.output):step.output)}</p></div>`:''}<h4>Justificatifs</h4><ul>${(step?.evidence||[n.evidence||'Les éléments seront produits au passage de cette étape.']).map(e=>`<li>${esc(typeof e==='object'?JSON.stringify(e):e)}</li>`).join('')}</ul><h4>Outils et appels</h4>${step?.tools?.length?step.tools.map(t=>`<div class="wf-tool-call"><code>${esc(typeof t==='string'?t:t.name||t.tool||'Outil')}</code><span>${esc(typeof t==='object'?t.status||'simulé':'simulé')}</span>${typeof t==='object'&&(t.args||t.input)?`<pre>${esc(JSON.stringify(t.args||t.input,null,2))}</pre>`:''}</div>`).join(''):'<p class="small muted">Aucun appel distant. Les activités sont simulées localement.</p>'}<div class="wf-step-io"><span>Entrées : ${esc((n.inputs||[]).join(', ')||'Dossier')}</span><span>Sorties : ${esc((n.outputs||[]).join(', ')||'Résultat vérifié')}</span></div></div></details>`;}).join('')}</div>
 <div class="wf-run-footer">${button('wf-run-snapshot','Inspecter l’instantané de version',{id:r.id,className:'btn-ghost btn-sm',iconName:'lock'})}${r.status==='running'?button('wf-run-advance','Poursuivre la simulation',{id:r.id,className:'btn-primary btn-sm',iconName:'play'}):''}${['waiting','running'].includes(r.status)?button('wf-cancel-run','Arrêter ce dossier',{id:r.id,className:'btn-ghost btn-sm'}):''}</div>`;
}

function renderOverview(p,s){
 const runs=processRuns(s,p.id);const completed=runs.filter(r=>r.status==='completed');const waiting=runs.filter(r=>r.status==='waiting');const metrics=runs.reduce((m,r)=>({cost:m.cost+(r.metrics?.cost||0),agent:m.agent+(r.metrics?.agentMinutes||0),human:m.human+(r.metrics?.humanMinutes||0)}),{cost:0,agent:0,human:0});
 const steps=(p.published||p.draft).nodes.slice().sort((a,b)=>(b.estimatedMinutes||0)-(a.estimatedMinutes||0));
 return `<div class="wf-tab-content"><div class="wf-overview-intro"><div class="eyebrow">L’OBJECTIF DU PROCESSUS</div><h2>${esc((p.published||p.draft).outcome)}</h2><p>Sous la responsabilité de ${esc(p.owner)}. Toutes les mesures ci-dessous proviennent des exemples et simulations de ce navigateur.</p></div><div class="stat-grid"><div class="stat-card"><div class="stat-label">Dossiers terminés</div><div class="stat-value">${completed.length}<small> / ${runs.length}</small></div><div class="stat-foot">Exemples et simulations</div></div><div class="stat-card"><div class="stat-label">Décisions en attente</div><div class="stat-value">${waiting.length}</div><div class="stat-foot">Responsable nommé à chaque attente</div></div><div class="stat-card"><div class="stat-label">Travail des agents</div><div class="stat-value">${fmt(metrics.agent)}<small> min</small></div><div class="stat-foot">Durées du scénario</div></div><div class="stat-card"><div class="stat-label">Coût simulé</div><div class="stat-value">${money(metrics.cost)}</div><div class="stat-foot">${fmt(metrics.human)} min de revue humaine</div></div></div><div class="grid-2"><section class="card"><div class="card-head"><div><h3 class="card-title">Où le temps se concentre</h3><p class="small muted">Durées de référence, configurées par étape</p></div></div><div class="wf-bottlenecks">${steps.slice(0,6).map(n=>`<button data-action="wf-node" data-id="${esc(n.id)}"><span><strong>${esc(n.name)}</strong><small>${n.kind==='human'?'Revue humaine':'Travail agent ou contrôle'}</small></span><span>${fmt(n.estimatedMinutes||0)} min</span><div>${progress((n.estimatedMinutes||0)/Math.max(...steps.map(x=>x.estimatedMinutes||1))*100,n.kind==='human'?'amber':'purple')}</div></button>`).join('')}</div></section><section class="card"><div class="card-head"><h3 class="card-title">Améliorations proposées</h3>${badge((p.improvements||[]).filter(x=>!x.applied).length,'purple')}</div><div class="wf-improvement-preview">${(p.improvements||[]).map(im=>`<div><strong>${esc(im.title)}</strong><p>${esc(im.description)}</p><small>${esc(im.impact||'Effet à mesurer')}</small>${im.applied?badge('Préparé dans le brouillon','green'):button('wf-apply-improvement','Préparer ce changement',{id:im.id,className:'btn-sm',iconName:'plus'})}</div>`).join('')||'<p class="muted">Aucune proposition pour le moment.</p>'}</div></section></div><div class="notice"><div><strong>Suivre les résultats acceptés.</strong><p>Une amélioration modifie le brouillon. Testez-la puis publiez une nouvelle version. Les dossiers déjà lancés conservent leur propre version.</p></div></div></div>`;
}

function renderSetup(p,s){
 const d=p.draft;
 return `<div class="wf-tab-content"><div class="wf-setup-layout"><section class="card wf-setup-card"><div class="card-head"><div><h2 class="card-title">Responsabilité et fonctionnement</h2><p class="small muted">Les paramètres de conception sont préparés dans le brouillon.</p></div>${button('wf-edit-setup','Modifier',{className:'btn-sm',iconName:'edit'})}</div><dl class="wf-setup-details"><dt>Résultat attendu</dt><dd>${esc(d.outcome)}</dd><dt>Responsable humain</dt><dd>${esc(p.owner)}</dd><dt>Agent coordinateur</dt><dd>${esc(actor(s,p.leadAgentId)?.name||'À affecter')}</dd><dt>Déclenchement</dt><dd>${esc(typeof d.trigger==='object'?d.trigger.label||JSON.stringify(d.trigger):d.trigger||'Démarrage manuel')}</dd><dt>Délai global</dt><dd>${fmt(d.deadlineHours||72)} heures</dd><dt>Mode d’autonomie</dt><dd>${esc(autonomyLabels[d.autonomy]||d.autonomy||'Dans les limites du mandat')}</dd></dl></section><section class="card wf-setup-card"><div class="card-head"><h2 class="card-title">Mise en service</h2>${badge(p.status==='live'?'En service':p.status==='paused'?'Suspendu':'Brouillon',p.status==='live'?'green':'neutral')}</div><div class="wf-setup-body"><p>La mise en service utilise la dernière version publiée. Une suspension empêche les nouveaux dossiers ; les dossiers existants peuvent encore recevoir leurs décisions.</p>${button('wf-toggle-live',p.status==='live'?'Suspendre les nouveaux départs':'Autoriser les nouveaux départs',{className:p.status==='live'?'':'btn-primary',iconName:p.status==='live'?'pause':'play'})}<div class="separator"></div><h3>Versions</h3><p>Version publiée : <strong>${p.version||0}</strong><br>Brouillon : <strong>${dirty(p)?'Modifications en préparation':'Identique à la version publiée'}</strong></p>${button('wf-version-history','Voir les versions',{className:'btn-ghost btn-sm',iconName:'history'})}</div></section></div><section class="card wf-setup-card"><div class="card-head"><h2 class="card-title">Phases et engagements de délai</h2>${button('wf-add-stage','Ajouter une phase',{className:'btn-sm',iconName:'plus'})}</div><div class="wf-stage-settings">${d.stages.map((st,i)=>`<div><span class="wf-stage-index">${i+1}</span><strong>${esc(st.name)}</strong><span>${fmt(st.deadlineHours)} h</span><span class="muted">${d.nodes.filter(n=>n.stageId===st.id).length} étapes</span>${button('wf-stage','Modifier',{id:st.id,className:'btn-ghost btn-sm',iconName:'edit'})}</div>`).join('')}</div></section><div class="notice"><div>Temporal et Mastra sont prévus pour l’exécution réelle. Cette version utilise un moteur de simulation local, sans connexion ni modèle distant.</div></div></div>`;
}

function openNode(n,p,s,ctx){
 const candidates=getFitCandidates(s,n);
 const primary=candidates.find(c=>c.id===n.agentId)||candidates[0];
 ctx.drawer({title:n.name,subtitle:`${p.draft.stages.find(st=>st.id===n.stageId)?.name||'Phase'} · ${kindLabels[n.kind]}`,body:`<div class="row between">${badge(n.staffing==='best'?'Meilleur profil disponible':n.staffing==='shadow'?'Challenger en observation':'Affectation fixe','purple')}${button('wf-edit-node','Modifier cette étape',{id:n.id,className:'btn-primary btn-sm',iconName:'edit'})}</div><h3 class="section-title">Résultat attendu</h3><p>${esc(n.outcome)}</p><h3 class="section-title">Ce qui prouve que le travail est terminé</h3><p class="muted">${esc(n.evidence||'Un résultat vérifiable et ses sources.')}</p><div class="tag-list">${(n.skills||[]).map(skill=>`<span class="tag">${esc(skill)}</span>`).join('')}</div><h3 class="section-title">Responsabilité</h3><dl class="detail-grid"><div class="detail-item"><dt>Exécutant</dt><dd>${esc(n.kind==='human'?n.owner:actor(s,n.agentId)?.name||primary?.name||'À affecter')}</dd></div><div class="detail-item"><dt>Escalade humaine</dt><dd>${esc(n.owner||p.owner)}</dd></div><div class="detail-item"><dt>Budget maximal</dt><dd>${money(n.spendLimit||0)}</dd></div><div class="detail-item"><dt>Action externe</dt><dd>${({allow:'Dans le mandat',ask:'Validation préalable',never:'Interdite'})[n.external]||'Validation préalable'}</dd></div><div class="detail-item"><dt>Seuil de qualité</dt><dd>${Math.round((n.confidence||.85)*100)}%</dd></div><div class="detail-item"><dt>Durée de référence</dt><dd>${fmt(n.estimatedMinutes||12)} min</dd></div></dl><h3 class="section-title">Entrées et sorties</h3><div class="wf-io-card"><div><strong>Entrées</strong>${(n.inputs||[]).map(x=>`<span>${esc(x)}</span>`).join('')||'<span>Dossier</span>'}</div><div><strong>Sorties</strong>${(n.outputs||[]).map(x=>`<span>${esc(x)}</span>`).join('')||'<span>Résultat vérifié</span>'}</div></div><h3 class="section-title">Dépendances</h3><p class="small muted">${(n.deps||[]).map(id=>esc(nodeName(p.draft,id))).join(' · ')||'Cette étape peut commencer dès le déclenchement.'}</p>${n.kind!=='human'?`<h3 class="section-title">Profils possibles</h3><p class="small muted">Adéquation calculée dans le scénario. Les profils du catalogue sont fictifs et restent soumis à qualification.</p><div class="wf-candidates">${candidates.slice(0,5).map(c=>`<div><span class="avatar avatar-agent">${icon('bot',15)}</span><div><strong>${esc(c.name)}</strong><small>${({own:'Votre équipe',shared:'Partagé',catalog:'Catalogue'})[c.source]||c.source} · ${c.verified?'Profil évalué dans le scénario':'Qualification nécessaire'}</small><p>${esc(c.reason)}</p></div><span>${Math.round(c.fit>1?c.fit:c.fit*100)}%</span>${button('wf-assign-candidate','Affecter',{id:n.id,value:c.id,className:'btn-ghost btn-sm'})}</div>`).join('')}</div>`:''}<div class="separator"></div><div class="row">${button('wf-duplicate-node','Dupliquer',{id:n.id,className:'btn-sm',iconName:'plus'})}${button('wf-remove-node','Retirer cette étape',{id:n.id,className:'btn-danger btn-sm'})}</div>`});
}

function editNode(n,p,s,ctx){
 ctx.closeDrawer();
 const candidates=getFitCandidates(s,n);
 ctx.modal({title:`Configurer · ${n.name}`,subtitle:'Les changements restent dans le brouillon jusqu’à publication.',body:`<div class="field"><label for="wf-node-name">Nom de l’étape</label><input id="wf-node-name" name="name" required maxlength="100" value="${esc(n.name)}"></div><div class="field"><label for="wf-node-outcome">Résultat attendu et instructions</label><textarea id="wf-node-outcome" name="outcome" required rows="3">${esc(n.outcome)}</textarea></div><div class="field"><label for="wf-node-evidence">Preuves / critères d’acceptation</label><textarea id="wf-node-evidence" name="evidence" rows="2">${esc(n.evidence||'')}</textarea></div><div class="form-grid"><div class="field"><label for="wf-node-kind">Qui réalise l’étape ?</label><select name="kind" id="wf-node-kind">${options([{id:'agent',name:'Agent'},{id:'human',name:'Humain'},{id:'tool',name:'Outil / contrôle'}],n.kind)}</select></div><div class="field"><label for="wf-node-stage">Phase</label><select name="stageId" id="wf-node-stage">${options(p.draft.stages,n.stageId)}</select></div><div class="field"><label for="wf-node-staffing">Mode d’affectation</label><select name="staffing" id="wf-node-staffing">${options([{id:'best',name:'Meilleur profil disponible'},{id:'fixed',name:'Profil fixe'},{id:'shadow',name:'Profil fixe + challenger en observation'}],n.staffing)}</select></div><div class="field"><label for="wf-node-agent">Agent affecté</label><select name="agentId" id="wf-node-agent">${options(candidates.map(c=>({id:c.id,name:`${c.name} · ${({own:'équipe',shared:'partagé',catalog:'catalogue'})[c.source]||c.source}`})),n.agentId)}</select></div><div class="field"><label for="wf-node-source">Périmètre de recherche</label><select name="source" id="wf-node-source">${options([{id:'own',name:'Votre équipe'},{id:'shared',name:'Agents partagés'},{id:'catalog',name:'Catalogue'}],n.source)}</select></div><div class="field"><label for="wf-node-challenger">Challenger</label><select name="challengerId" id="wf-node-challenger"><option value="">Aucun challenger</option>${options(candidates.filter(c=>c.id!==n.agentId).map(c=>({id:c.id,name:c.name})),n.challengerId)}</select></div><div class="field"><label for="wf-node-owner">Humain responsable / escalade</label><select name="owner" id="wf-node-owner">${humanOptions(s,n.owner||p.owner)}</select></div><div class="field"><label for="wf-node-spend">Budget maximal (€)</label><input name="spendLimit" id="wf-node-spend" type="number" min="0" max="100000" step="1" required value="${Number(n.spendLimit)||0}"></div><div class="field"><label for="wf-node-external">Action externe</label><select name="external" id="wf-node-external">${options([{id:'never',name:'Jamais'},{id:'ask',name:'Demander avant d’agir'},{id:'allow',name:'Autoriser dans le mandat'}],n.external)}</select></div><div class="field"><label for="wf-node-confidence">Seuil de qualité (0 à 1)</label><input name="confidence" id="wf-node-confidence" type="number" min="0" max="1" step="0.01" required value="${Number(n.confidence)||.85}"></div><div class="field"><label for="wf-node-action">Action / outil simulé</label><input name="action" id="wf-node-action" required value="${esc(n.action||'prepare_result')}"></div><div class="field"><label for="wf-node-duration">Durée de référence (minutes)</label><input name="estimatedMinutes" id="wf-node-duration" type="number" min="1" max="10080" required value="${Number(n.estimatedMinutes)||15}"></div></div><div class="field"><label for="wf-node-condition">Branche du scénario</label><select name="condition" id="wf-node-condition">${options([{id:'',name:'Toujours, si les dépendances sont satisfaites'},{id:'bid',name:'Candidater'},{id:'decline',name:'Ne pas candidater'}],n.condition||'')}</select></div><div class="field"><label for="wf-node-skills">Compétences nécessaires</label><input name="skills" id="wf-node-skills" value="${esc((n.skills||[]).join(', '))}"><span class="form-help">Séparez les valeurs par une virgule.</span></div><div class="form-grid"><div class="field"><label for="wf-node-inputs">Entrées</label><input name="inputs" id="wf-node-inputs" value="${esc((n.inputs||[]).join(', '))}"></div><div class="field"><label for="wf-node-outputs">Sorties</label><input name="outputs" id="wf-node-outputs" value="${esc((n.outputs||[]).join(', '))}"></div></div><fieldset class="wf-deps-fieldset"><legend>Cette étape attend les sorties de…</legend>${p.draft.nodes.filter(x=>x.id!==n.id).map(x=>`<label><input type="checkbox" name="deps" value="${esc(x.id)}" ${(n.deps||[]).includes(x.id)?'checked':''}>${esc(x.name)}</label>`).join('')}</fieldset>`,submitLabel:'Enregistrer dans le brouillon',onSubmit:fd=>{const patch=Object.fromEntries(fd.entries());for(const key of ['spendLimit','confidence','estimatedMinutes'])patch[key]=Number(fd.get(key));for(const key of ['skills','inputs','outputs'])patch[key]=String(fd.get(key)||'').split(',').map(x=>x.trim()).filter(Boolean);patch.deps=fd.getAll('deps');const r=patchStep(p.id,n.id,patch);return finish(r,ctx,'Étape modifiée dans le brouillon.');}});
}

function stageModal(stage,p,ctx){
 ctx.modal({title:`Phase · ${stage.name}`,subtitle:'La phase regroupe les étapes et fixe leur engagement de délai.',body:`<div class="field"><label for="wf-stage-name">Nom de la phase</label><input id="wf-stage-name" name="name" value="${esc(stage.name)}" required></div><div class="form-grid"><div class="field"><label for="wf-stage-deadline">Délai maximal (heures)</label><input id="wf-stage-deadline" name="deadlineHours" type="number" min="0.1" max="8760" step="0.1" value="${Number(stage.deadlineHours)||8}" required></div><div class="field"><label for="wf-stage-order">Position dans le canevas</label><select id="wf-stage-order" name="order">${p.draft.stages.map((st,i)=>`<option value="${i}" ${st.id===stage.id?'selected':''}>${i+1} — ${esc(st.name)}</option>`).join('')}</select></div></div><p class="small muted">Les dépendances déterminent l’ordre d’exécution. Une phase ne peut pas être déplacée après une phase qui attend ses résultats.</p><div class="separator"></div>${button('wf-remove-stage','Supprimer cette phase',{id:stage.id,className:'btn-danger btn-sm'})}<p class="form-help">Une phase contenant des étapes doit d’abord être vidée.</p>`,onSubmit:fd=>finish(editDraft(p.id,d=>{const i=d.stages.findIndex(st=>st.id===stage.id);const st=d.stages.splice(i,1)[0];st.name=String(fd.get('name')).trim();st.deadlineHours=Number(fd.get('deadlineHours'));d.stages.splice(Number(fd.get('order')),0,st);},'Phase modifiée'),ctx,'Phase mise à jour dans le brouillon.')});
}
function connectionsModal(p,ctx){
 ctx.modal({title:'Relier les étapes et leurs données',subtitle:'Une dépendance attend la sortie de l’étape précédente. Les cycles et les liens invalides sont refusés.',body:`<div class="wf-edge-editor">${p.draft.edges.map((e,i)=>`<label class="wf-edge-item"><input type="checkbox" name="keepEdge" value="${i}" checked><span>${esc(nodeName(p.draft,e.from))} ${icon('arrow',13)} ${esc(nodeName(p.draft,e.to))}<small>${esc(e.label||'Dépendance de données')}</small></span></label>`).join('')}</div><div class="separator"></div><h3>Ajouter une dépendance</h3><div class="form-grid"><div class="field"><label for="wf-edge-from">Étape source</label><select id="wf-edge-from" name="from"><option value="">Aucun nouveau lien</option>${options(p.draft.nodes,'')}</select></div><div class="field"><label for="wf-edge-to">Étape dépendante</label><select id="wf-edge-to" name="to"><option value="">Choisir une destination</option>${options(p.draft.nodes,'')}</select></div></div><div class="field"><label for="wf-edge-label">Donnée / condition transmise</label><input id="wf-edge-label" name="label" placeholder="Ex. Dossier qualifié, prix validé…"></div>`,submitLabel:'Enregistrer les liens',onSubmit:fd=>{const keep=fd.getAll('keepEdge').map(Number);const edges=p.draft.edges.filter((e,i)=>keep.includes(i));const from=String(fd.get('from')||''),to=String(fd.get('to')||'');if(from&&!to){ctx.toast('Choisissez l’étape destinataire.');return false;}if(from&&to)edges.push({from,to,label:String(fd.get('label')||'').trim()});return finish(setEdges(p.id,edges),ctx,'Dépendances enregistrées.');}});
}
function setupModal(p,s,ctx){
 const d=p.draft;const trigger=typeof d.trigger==='object'?d.trigger.label||'Manuel':d.trigger;
 ctx.modal({title:'Configurer le processus',subtitle:'Les changements de conception seront publiés avec la prochaine version.',body:`<div class="field"><label for="wf-setup-name">Nom</label><input name="name" id="wf-setup-name" value="${esc(p.name)}" required></div><div class="field"><label for="wf-setup-outcome">Résultat attendu</label><textarea name="outcome" id="wf-setup-outcome" rows="3" required>${esc(d.outcome)}</textarea></div><div class="form-grid"><div class="field"><label for="wf-setup-owner">Responsable humain</label><select name="owner" id="wf-setup-owner">${humanOptions(s,p.owner)}</select></div><div class="field"><label for="wf-setup-lead">Agent coordinateur</label><select name="leadAgentId" id="wf-setup-lead">${options(s.agents.filter(a=>a.type==='agent'),p.leadAgentId)}</select></div><div class="field"><label for="wf-setup-trigger">Déclencheur</label><select name="trigger" id="wf-setup-trigger">${options([...new Set([trigger,'Démarrage manuel','Réception d’un document','Événement métier','Chaque matin à 08:00','Chaque semaine'].filter(Boolean))],trigger)}</select></div><div class="field"><label for="wf-setup-deadline">Délai global (heures)</label><input name="deadlineHours" id="wf-setup-deadline" type="number" min="1" max="8760" required value="${Number(d.deadlineHours)||72}"></div><div class="field"><label for="wf-setup-autonomy">Mode d’autonomie</label><select name="autonomy" id="wf-setup-autonomy">${options(Object.entries(autonomyLabels).map(([id,name])=>({id,name})),d.autonomy)}</select></div><div class="field"><label for="wf-setup-team">Équipe</label><select name="team" id="wf-setup-team">${options([...new Set(s.agents.map(a=>a.team))],p.team)}</select></div></div><p class="form-help">Les déclencheurs sont décrits et enregistrés ; ils ne créent aucune planification ou connexion externe dans le démonstrateur.</p>`,onSubmit:fd=>{const data=Object.fromEntries(fd.entries());data.deadlineHours=Number(data.deadlineHours);return finish(updateSetup(p.id,data),ctx,'Configuration du processus enregistrée.');}});
}
function improvementDrawer(p,ctx){ctx.drawer({title:'Améliorer le processus',subtitle:'Propositions du scénario, à vérifier dans un test avant publication.',body:(p.improvements||[]).map(im=>`<article class="card wf-improvement"><span class="icon-box">${icon('activity',16)}</span><h3>${esc(im.title)}</h3><p>${esc(im.description)}</p><p class="small muted">${esc(im.impact||'Effet à mesurer')}</p>${im.applied?badge('Changement préparé','green'):button('wf-apply-improvement','Préparer dans le brouillon',{id:im.id,className:'btn-primary btn-sm',iconName:'plus'})}</article>`).join('')||empty('Aucune proposition','Les simulations locales alimentent l’inspection du travail.')});}
function startModal(p,ctx,isTest=false){
 ctx.modal({title:isTest?'Tester le brouillon':'Lancer un dossier simulé',subtitle:isTest?'Le test utilise un instantané du brouillon. Il ne modifie pas la version en service.':`Le dossier utilisera la version publiée ${p.version}. Aucun effet externe.`,body:`<div class="field"><label for="wf-run-title">Nom du dossier</label><input id="wf-run-title" name="title" required maxlength="120" value="${esc(isTest?'Test de conception':`${p.name} · nouveau dossier`)}"></div>${p.draft.nodes.some(n=>n.condition)?`<div class="field"><label for="wf-run-scenario">Branche à explorer dans le scénario</label><select id="wf-run-scenario" name="scenario"><option value="bid">Candidater — préparer et remettre la réponse</option><option value="decline">Ne pas candidater — préparer un refus motivé</option></select></div>`:''}<div class="notice"><div>Le moteur local avance jusqu’à la prochaine décision. Chaque approbation reprend le parcours à l’étape suivante, avec son propre mandat.</div></div>`,submitLabel:isTest?'Lancer le test':'Lancer la simulation',onSubmit:fd=>{const result=startRun(p.id,{draft:isTest,title:String(fd.get('title')).trim(),scenario:String(fd.get('scenario')||'bid')});if(!finish(result,ctx,isTest?'Test du brouillon lancé.':'Dossier lancé sur la version publiée.'))return false;view.runId=result.runId;view.tab='runs';view.runFilter='all';ctx.render();}});
}
function approvalModal(el,r,ctx){
 const outcome=el.dataset.value;const saved={requestId:el.dataset.request,token:el.dataset.token,outcome};const title=outcome==='deny'?'Refuser cette action':outcome==='always'?'Définir une délégation récurrente':'Autoriser cette action une fois';
 ctx.modal({title,subtitle:r.request?.title||'Décision de gouvernance',body:`<div class="notice"><div>${outcome==='always'?'Cette autorisation couvre uniquement le même agent, la même action et ce processus, avec un mandat inchangé. Elle ne supprime aucune étape humaine ni interdiction.':outcome==='deny'?'Le dossier sera arrêté. Les étapes déjà simulées restent conservées dans son historique.':'La décision est liée à cette demande précise. Si son affectation ou son contenu a changé, elle sera refusée.'}</div></div><div class="field"><label for="wf-approval-comment">Motif / commentaire ${outcome==='deny'?'(requis)':'(facultatif)'}</label><textarea id="wf-approval-comment" name="comment" rows="3" ${outcome==='deny'?'required':''} placeholder="Documentez votre décision…"></textarea></div>`,submitLabel:outcome==='deny'?'Refuser et arrêter':outcome==='always'?'Enregistrer cette délégation':'Autoriser une fois',onSubmit:fd=>{const result=resolveApproval(r.id,{...saved,comment:String(fd.get('comment')||'')});return finish(result,ctx,outcome==='deny'?'Action refusée, dossier arrêté.':'Décision enregistrée. Le parcours poursuit jusqu’au prochain contrôle.');}});
}

export function handleWorkflows(action,el,ctx){
 if(!action?.startsWith('wf-'))return false;
 const s=ctx.getState();const p=studioProcess(s,view.processId);const id=el.dataset.id;const value=el.dataset.value;
 if(action==='wf-back'){view.processId=null;view.runId=null;ctx.render();return true;}
 if(action==='wf-open'){openWorkflow(id,ctx);return true;}
 if(action==='wf-open-run'){openWorkflowRun(id,ctx);return true;}
 if(action==='wf-template'){const template=listTemplates().find(t=>t.id===id);const result=createProcess(template?.outcome||template?.title||'Préparer un résultat fiable',id);if(finish(result,ctx,'Processus préparé à partir du modèle.'))openWorkflow(result.processId,ctx);return true;}
 if(action==='wf-create'){const outcome=document.getElementById('wf-outcome')?.value?.trim();if(!outcome){ctx.toast('Décrivez le résultat à obtenir.');document.getElementById('wf-outcome')?.focus();return true;}const result=createProcess(outcome);if(finish(result,ctx,'Brouillon préparé. Vérifiez les étapes et leurs responsabilités.'))openWorkflow(result.processId,ctx);return true;}
 if(!p){ctx.toast('Ouvrez d’abord un processus.');return true;}
 if(action==='wf-tab'){view.tab=value;ctx.closeDrawer?.();ctx.render();}
 else if(action==='wf-lens'){view.lens=value;ctx.render();}
 else if(action==='wf-diff'){view.showChanges=!view.showChanges;ctx.render();}
 else if(action==='wf-zoom-in'){view.zoom=Math.min(1.5,view.zoom+.1);ctx.render();}
 else if(action==='wf-zoom-out'){view.zoom=Math.max(.35,view.zoom-.1);ctx.render();}
 else if(action==='wf-fit'){const width=document.getElementById('wf-canvas-scroll')?.clientWidth||1000;view.zoom=Math.max(.35,Math.min(1,(width-35)/designLayout(p.draft).width));ctx.render();}
 else if(action==='wf-undo')finish(undoDraft(p.id),ctx,'Dernière modification annulée.');
 else if(action==='wf-redo')finish(redoDraft(p.id),ctx,'Modification rétablie.');
 else if(action==='wf-node'){const selected=processRuns(s,p.id).find(r=>r.id===view.runId)||processRuns(s,p.id).find(r=>r.status==='waiting')||processRuns(s,p.id)[0];const d=view.lens==='live'?(selected?.snapshot||p.published||p.draft):p.draft;const n=d.nodes.find(n=>n.id===id);if(n)openNode(n,{...p,draft:d},s,ctx);}
 else if(action==='wf-edit-node'){const n=p.draft.nodes.find(n=>n.id===id);if(n){view.lens='design';editNode(n,p,s,ctx);}else ctx.toast('Cette étape n’existe plus dans le brouillon.');}
 else if(action==='wf-assign-candidate'){const candidate=getFitCandidates(s,p.draft.nodes.find(n=>n.id===id)||{}).find(c=>c.id===value);const result=patchStep(p.id,id,{agentId:value,staffing:'fixed',source:candidate?.source||'own'});if(finish(result,ctx,candidate?.source==='catalog'?'Profil du catalogue affecté dans le scénario ; qualification à prévoir.':'Agent affecté à cette étape.'))ctx.closeDrawer();}
 else if(action==='wf-duplicate-node'){if(finish(duplicateStep(p.id,id),ctx,'Étape dupliquée dans le brouillon.'))ctx.closeDrawer();}
 else if(action==='wf-remove-node'){ctx.closeDrawer();ctx.modal({title:'Retirer cette étape',subtitle:'Les liens entrants et sortants seront retirés. Vérifiez ensuite les dépendances.',body:`<p>${esc(p.draft.nodes.find(n=>n.id===id)?.name||'Étape')}</p>`,submitLabel:'Retirer du brouillon',onSubmit:()=>finish(removeStep(p.id,id),ctx,'Étape retirée, dépendances nettoyées.')});}
 else if(action==='wf-add-step'){ctx.modal({title:'Ajouter une étape',subtitle:p.draft.stages.find(st=>st.id===id)?.name,body:`<div class="field"><label for="wf-add-name">Nom</label><input id="wf-add-name" name="name" required placeholder="Ex. Vérifier les engagements"></div><div class="field"><label for="wf-add-outcome">Résultat attendu</label><textarea id="wf-add-outcome" name="outcome" rows="2" required></textarea></div><div class="form-grid"><div class="field"><label for="wf-add-kind">Exécutant</label><select id="wf-add-kind" name="kind">${options([{id:'agent',name:'Agent'},{id:'human',name:'Humain'},{id:'tool',name:'Outil / contrôle'}],'agent')}</select></div><div class="field"><label for="wf-add-agent">Agent</label><select id="wf-add-agent" name="agentId">${options(s.agents.filter(a=>a.type==='agent'),p.leadAgentId)}</select></div><div class="field"><label for="wf-add-owner">Responsable humain</label><select id="wf-add-owner" name="owner">${humanOptions(s,p.owner)}</select></div><div class="field"><label for="wf-add-dep">Commencer après</label><select id="wf-add-dep" name="dep"><option value="">Dès le déclenchement</option>${options(p.draft.nodes,'')}</select></div></div>`,onSubmit:fd=>finish(addStep(p.id,{stageId:id,name:String(fd.get('name')).trim(),outcome:String(fd.get('outcome')).trim(),kind:String(fd.get('kind')),agentId:String(fd.get('agentId')),owner:String(fd.get('owner')),deps:fd.get('dep')?[String(fd.get('dep'))]:[],staffing:'fixed',source:'own',external:'ask',confidence:.85,spendLimit:50,estimatedMinutes:15,skills:[],inputs:['dossier'],outputs:['résultat vérifié']}),ctx,'Nouvelle étape ajoutée au brouillon.')});}
 else if(action==='wf-stage'){const stage=p.draft.stages.find(st=>st.id===id);if(stage)stageModal(stage,p,ctx);}
 else if(action==='wf-add-stage')ctx.modal({title:'Ajouter une phase',subtitle:'Une nouvelle colonne dans le canevas.',body:'<div class="field"><label for="wf-new-stage">Nom de la phase</label><input id="wf-new-stage" name="name" required placeholder="Ex. Archivage"></div><div class="field"><label for="wf-new-deadline">Délai en heures</label><input id="wf-new-deadline" name="deadlineHours" type="number" min="0.1" max="8760" step="0.1" value="4" required></div>',onSubmit:fd=>finish(addStage(p.id,{name:String(fd.get('name')).trim(),deadlineHours:Number(fd.get('deadlineHours'))}),ctx,'Phase ajoutée. Ajoutez-y les étapes nécessaires.')});
 else if(action==='wf-remove-stage'){if(finish(removeStage(p.id,id),ctx,'Phase retirée du brouillon.'))ctx.closeModal();}
 else if(action==='wf-connections')connectionsModal(p,ctx);
 else if(action==='wf-validation'){const v=validateDraft(p.draft);ctx.drawer({title:'Vérifier la structure',subtitle:v.ok?'Le processus est structurellement valide.':'Corrigez ces points avant de publier.',body:v.ok?'<p>Phases, étapes, affectations et dépendances cohérentes.</p>':`<ul class="evidence">${v.errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul>`});}
 else if(action==='wf-discard')ctx.modal({title:'Abandonner le brouillon',subtitle:'Le canevas retrouvera la dernière version publiée. Les dossiers existants ne changent pas.',body:'<p class="small muted">Les modifications de conception non publiées seront retirées.</p>',submitLabel:'Restaurer la version publiée',onSubmit:()=>finish(discardDraft(p.id),ctx,'Brouillon restauré depuis la version publiée.')});
 else if(action==='wf-publish'){const validation=validateDraft(p.draft);if(!validation.ok){ctx.toast(validation.errors.join(' · '));return true;}if(!dirty(p)&&p.version>0){ctx.toast('La conception correspond déjà à la version publiée.');return true;}ctx.modal({title:`Publier la version ${(p.version||0)+1}`,subtitle:'Les nouveaux dossiers utiliseront cette version. Les dossiers ouverts conservent leur instantané.',body:`<div class="wf-publish-summary"><div><strong>${p.draft.stages.length}</strong><span>phases</span></div><div><strong>${p.draft.nodes.length}</strong><span>étapes</span></div><div><strong>${p.draft.nodes.filter(n=>n.kind==='human').length}</strong><span>étapes humaines</span></div></div><p>${esc(p.draft.outcome)}</p><div class="notice"><div>La publication concerne le moteur de simulation local. Aucun déploiement Temporal ou Mastra n’est lancé.</div></div>`,submitLabel:'Publier cette version',onSubmit:()=>finish(publishDraft(p.id),ctx,'Nouvelle version publiée pour les prochaines simulations.')});}
 else if(action==='wf-natural'){const text=document.getElementById('wf-natural-request')?.value?.trim();if(!text){ctx.toast('Décrivez une modification à préparer.');return true;}const result=naturalChange(p.id,text);if(finish(result,ctx,result.explanation||'Changement préparé localement dans le brouillon.')){view.lens='design';ctx.render();}}
 else if(action==='wf-improvements')improvementDrawer(p,ctx);
 else if(action==='wf-apply-improvement'){if(finish(applyImprovement(p.id,id),ctx,'Amélioration préparée dans le brouillon. Testez-la avant publication.'))ctx.closeDrawer();}
 else if(action==='wf-test')startModal(p,ctx,true);
 else if(action==='wf-start')startModal(p,ctx,false);
 else if(action==='wf-run-filter'){view.runFilter=value;view.runId=null;ctx.render();}
 else if(action==='wf-run-select'){view.runId=id;ctx.render();}
 else if(action==='wf-follow'){view.runId=el.dataset.id||view.runId;view.tab='design';view.lens='live';ctx.render();}
 else if(action==='wf-approve'){const r=s.studio.runs.find(r=>r.id===id);if(r)approvalModal(el,r,ctx);}
 else if(action==='wf-reassign'){const r=s.studio.runs.find(r=>r.id===id);if(r?.request)ctx.modal({title:'Réaffecter cette décision',subtitle:'La demande conservera son action exacte, avec un nouveau responsable et un jeton de décision renouvelé.',body:`<div class="field"><label for="wf-reviewer">Responsable de la décision</label><select name="owner" id="wf-reviewer">${humanOptions(s,r.request.owner)}</select></div>`,submitLabel:'Réaffecter',onSubmit:fd=>finish(reassignApproval(r.id,String(fd.get('owner'))),ctx,'Décision réaffectée au responsable choisi.')});}
 else if(action==='wf-cancel-run')ctx.modal({title:'Arrêter ce dossier',subtitle:'L’historique sera conservé ; aucune nouvelle étape ne sera exécutée.',body:'<p class="small muted">Cette action concerne uniquement le dossier simulé sélectionné.</p>',submitLabel:'Arrêter le dossier',onSubmit:()=>finish(cancelRun(id),ctx,'Dossier arrêté.')});
 else if(action==='wf-run-advance')finish(advanceRun(id),ctx,'Simulation avancée jusqu’au prochain contrôle.');
 else if(action==='wf-run-snapshot'){const r=s.studio.runs.find(r=>r.id===id);if(r)ctx.drawer({title:`Instantané · version ${r.version}`,subtitle:'Cette conception est conservée avec le dossier, indépendamment des changements ultérieurs.',body:`<p>${esc(r.snapshot.outcome)}</p><h3 class="section-title">Étapes de cette version</h3>${r.snapshot.nodes.map(n=>`<div class="wf-snapshot-row"><strong>${esc(n.name)}</strong><span>${kindLabels[n.kind]} · ${esc(n.owner)}</span></div>`).join('')}<details class="wf-request-evidence"><summary>Voir l’instantané complet</summary><pre>${esc(JSON.stringify(r.snapshot,null,2))}</pre></details>`});}
 else if(action==='wf-edit-setup')setupModal(p,s,ctx);
 else if(action==='wf-toggle-live'){const next=p.status==='live'?'paused':'live';finish(updateSetup(p.id,{status:next}),ctx,next==='paused'?'Nouveaux départs suspendus. Les dossiers en cours restent accessibles.':'Nouveaux départs autorisés sur la version publiée.');}
 else if(action==='wf-version-history'){const versions=p.versions||p.history||[];ctx.drawer({title:'Historique des versions',subtitle:'Une nouvelle publication ne modifie jamais les dossiers déjà ouverts.',body:`<div class="card"><strong>Version publiée ${p.version}</strong><p class="small muted">${p.published?.nodes.length||0} étapes · ${p.published?.stages.length||0} phases</p></div>${versions.map(v=>`<div class="card"><strong>Version ${esc(v.version||v.number)}</strong><p class="small muted">${time(v.publishedAt||v.createdAt)} · ${v.snapshot?.nodes?.length||v.design?.nodes?.length||'—'} étapes</p></div>`).join('')}<p class="small muted">Les instantanés sont également disponibles dans chaque exécution.</p>`});}
 else return false;
 return true;
}
